def populate_ticket_numbers(apps, schema_editor):
    ticket_model = apps.get_model("tickets", "Ticket")
    for ticket in ticket_model.objects.filter(ticket_number__isnull=True).iterator():
        year = ticket.created_at.year if ticket.created_at else 2026
        while True:
            number = f"TKT-{year}-{uuid.uuid4().hex[:12].upper()}"
            if not ticket_model.objects.filter(ticket_number=number).exists():
                break
        ticket_model.objects.filter(pk=ticket.pk).update(ticket_number=number)


